    {
      "ledger_id": "A1",
      "description": "Email to landlord Ava confirming the 15 September next reading date"
    },
    {
      "ledger_id": "A2",
      "description": "Email to tenant Miles Fletcher thanking him and noting the next reading date"
    },
    {
      "ledger_id": "A4",
      "description": "Ticket NBL-010-recurring returned to auto mode"
    },
    {
      "ledger_id": "A5",
      "description": "Follow-up FUP-103 set for 2025-09-01 to request the tenant's photo"
    },
    {
      "ledger_id": "A6",
      "description": "Ticket on hold until 2025-09-01 for the photo request"
    }
  ],
  "failed_actions": [
    {
      "ledger_id": "A3",
      "handling": "First resume_auto used the case label 010-recurring, which was not found. Retried with the real ref NBL-010-recurring from list_tickets, which verified as A4."
